@push('scripts')<script>
(()=>{
 const root=document.getElementById('sections'),sumEl=document.getElementById('marksSum'),status=document.getElementById('marksStatus'),total=document.getElementById('totalMarks');let si=0;
 const fmt=n=>Number(n||0).toFixed(2).replace(/\.00$/,'').replace(/(\.\d)0$/,'$1');
 function update(){let grand=0;root.querySelectorAll('.section-box').forEach(box=>{const count=box.querySelectorAll('.question-row').length;const answer=box.querySelector('.answer-count');answer.max=count;if(+answer.value>count)answer.value=count;const wanted=Math.max(1,Math.min(parseInt(answer.value||1,10),count));const mark=parseFloat(box.querySelector('.per-question-marks').value)||0;const sectionTotal=mark*wanted;grand+=sectionTotal;const out=box.querySelector('.section-mark-summary');if(out)out.textContent=`বিভাগের নম্বর: ${fmt(mark)} × ${wanted} = ${fmt(sectionTotal)}`;});total.value=fmt(grand);sumEl.textContent=fmt(grand);status.textContent=`পরীক্ষার পূর্ণমান স্বয়ংক্রিয়ভাবে হিসাব হয়েছে: ${fmt(grand)}`;status.className='mt-2 text-sm text-emerald-700';}
 function renumber(section){section.querySelectorAll('.question-row').forEach((q,i)=>q.querySelector('.q-label').textContent=`প্রশ্ন ${i+1}`);}
 function addQuestion(section,idx,data={}){const before=section.querySelectorAll('.question-row').length,answer=section.querySelector('.answer-count');const wasAll=+answer.value===before;let qi=Number(section.dataset.qcount||0);section.dataset.qcount=qi+1;let wrap=document.createElement('div');wrap.className='question-row rounded-lg border bg-white p-3';wrap.innerHTML=`<div class="mb-2 flex justify-between"><b class="q-label">প্রশ্ন</b><button type="button" class="remove text-sm text-rose-600">মুছুন</button></div><label class="mb-1 block text-xs font-semibold">অধ্যায় / টপিক</label><input class="field mb-2" name="sections[${idx}][questions][${qi}][topic]" placeholder="অধ্যায় / ইউনিট / টপিক"><label class="mb-1 block text-xs font-semibold">প্রশ্নের বিবরণ *</label><textarea required rows="3" class="field mb-2" name="sections[${idx}][questions][${qi}][text]" placeholder="প্রশ্ন লিখুন। উপপ্রশ্ন থাকলে ক), খ), গ) আলাদা লাইনে লিখুন।"></textarea><label class="mb-1 block text-xs font-semibold">প্রশ্নের ধরন</label><select class="field" name="sections[${idx}][questions][${qi}][type]"><option>Creative</option><option>Short</option><option>MCQ</option><option>Practical</option></select>`;
  wrap.querySelector('[name$="[topic]"]').value=data.topic||'';wrap.querySelector('textarea').value=data.text||'';wrap.querySelector('select').value=data.type||'Creative';
  wrap.querySelector('.remove').onclick=()=>{if(section.querySelectorAll('.question-row').length<=1){alert('একটি বিভাগে কমপক্ষে ১টি প্রশ্ন রাখতে হবে।');return}const oldCount=section.querySelectorAll('.question-row').length,wasAll=+answer.value===oldCount;wrap.remove();renumber(section);if(wasAll)answer.value=section.querySelectorAll('.question-row').length;update()};
  section.querySelector('.question-list').append(wrap);renumber(section);if(wasAll)answer.value=section.querySelectorAll('.question-row').length;update();}
 function addSection(title='',instruction='',questions=[],answerCount=null,perQuestionMarks=null){const idx=si++,box=document.createElement('div');box.className='section-box rounded-xl border-2 border-slate-200 p-4';box.dataset.qcount='0';const fallbackMark=questions.length?(questions[0].marks??1):1;box.innerHTML=`<div class="mb-3 flex flex-wrap items-center justify-between gap-2"><b class="section-label">বিভাগ</b><button type="button" class="remove-section text-sm font-semibold text-rose-600">বিভাগ মুছুন</button></div><div class="grid gap-3 md:grid-cols-2"><div><label class="mb-1 block text-sm font-semibold">বিভাগের নাম *</label><input required class="field" name="sections[${idx}][title]" value="${title}" placeholder="যেমন: গ-বিভাগ"></div><div><label class="mb-1 block text-sm font-semibold">মোট প্রশ্নের মধ্যে কয়টির উত্তর দিতে হবে? *</label><input type="number" min="1" step="1" class="field answer-count" name="sections[${idx}][answer_count]" value="${answerCount??Math.max(1,questions.length)}" required></div><div><label class="mb-1 block text-sm font-semibold">প্রতি প্রশ্নের নম্বর *</label><input type="number" min="0.25" step="0.25" class="field per-question-marks" name="sections[${idx}][per_question_marks]" value="${perQuestionMarks??fallbackMark}" required></div><div><label class="mb-1 block text-sm font-semibold">নির্দেশনা (ঐচ্ছিক)</label><input class="field" name="sections[${idx}][instruction]" value="${instruction}" placeholder="যেমন: যে কোনো ১টি প্রশ্নের উত্তর দাও"></div></div><div class="question-list mt-3 space-y-3"></div><div class="mt-3 rounded-lg bg-blue-50 p-3 text-sm text-blue-800 section-mark-summary"></div><button type="button" class="add-question mt-3 rounded-lg border border-blue-200 px-3 py-2 text-sm font-semibold text-blue-700">＋ এই বিভাগে প্রশ্ন যুক্ত করুন</button>`;
  box.querySelector('.add-question').onclick=()=>addQuestion(box,idx);box.querySelector('.answer-count').oninput=update;box.querySelector('.per-question-marks').oninput=update;box.querySelector('.remove-section').onclick=()=>{if(root.querySelectorAll('.section-box').length<=1){alert('কমপক্ষে একটি বিভাগ রাখতে হবে।');return}box.remove();update()};root.append(box);if(questions.length)questions.forEach(q=>addQuestion(box,idx,q));else addQuestion(box,idx);renumber(box);update();return box;}
 document.getElementById('addSection').onclick=()=>addSection('নতুন বিভাগ','',[],1,1);
 const initialSections=@json(old('sections', $question ? ($question->questions['sections'] ?? []) : []));
 if(initialSections.length){initialSections.forEach(sec=>addSection(sec.title||'',sec.instruction||'',sec.questions||[],sec.answer_count??(sec.questions||[]).length,sec.per_question_marks??(sec.questions?.[0]?.marks??1)));}
 else{addSection('ক-বিভাগ','',[{marks:1}],2,1);addSection('খ-বিভাগ','',[{marks:2}],2,2);addSection('গ-বিভাগ','',[{marks:5},{marks:5}],1,5);}
 update();
})();
</script>@endpush
